import { useState } from "react";
import type { CSSProperties, ReactElement } from "react";

export type Props = { initialCents: string; initialPeople: string };

const panelStyle: CSSProperties = {
  background: "#eef4ff",
  color: "#17345c",
  padding: "12px",
  gap: "6px",
  display: "grid",
};

function parseUnsignedInteger(input: string): number | null {
  const text: string = input.trim();
  if (!/^[0-9]+$/.test(text)) return null;
  const value: number = Number(text);
  return Number.isSafeInteger(value) && value >= 0 ? value : null;
}

function allocate(centsText: string, peopleText: string): string {
  const cents: number | null = parseUnsignedInteger(centsText);
  const people: number | null = parseUnsignedInteger(peopleText);
  if (cents === null || people === null || people < 1 || people > 20) {
    return "Invalid allocation";
  }
  const base: number = Math.floor(cents / people);
  const remainder: number = cents % people;
  const amounts: number[] = Array.from(
    { length: people },
    (_unused, index): number => base + (index < remainder ? 1 : 0),
  );
  return amounts.join(", ");
}

export function Component({ initialCents, initialPeople }: Props): ReactElement {
  const [cents, setCents] = useState<string>(initialCents);
  const [people, setPeople] = useState<string>(initialPeople);
  const allocation: string = allocate(cents, people);

  return (
    <div data-testid="panel" style={panelStyle}>
      <label>
        Cents
        <input
          type="text"
          value={cents}
          onChange={(event) => setCents(event.currentTarget.value)}
        />
      </label>
      <label>
        People
        <input
          type="text"
          value={people}
          onChange={(event) => setPeople(event.currentTarget.value)}
        />
      </label>
      <output aria-label="Allocation">{allocation}</output>
    </div>
  );
}
